for(const item of bank)if(item.subject==="russian"&&item.topic==="Сочинение · Письменная практика")item.topicOrder=8;
if(!bank.some(item=>item.id===test.id))bank.push(test);
const ordered=bank.filter(t=>t.subject==="russian").sort((a,b)=>a.topicOrder-b.topicOrder||a.part-b.part);
